// ENTRADA: el inject "Iniciar"
// SALIDA:  una suscripción por variable: la última pieza inspeccionada, el último molde colado y la avería activa

const PIEZA = { Id: "String", Molde: "String", Prensa: "String", Lote: "String",
                TemperaturaColada: "Double", HumedadArena: "Double", Inoculada: "Boolean",
                TiempoEnfriamiento: "Double", TemperaturaDesmoldeo: "Double",
                Desviacion: "Double", Resultado: "String", Defecto: "String" };
const COLADA = { Molde: "String", Prensa: "String", Lote: "String",
                 TemperaturaColada: "Double", HumedadArena: "Double", Inoculada: "Boolean" };
const m = [];
for (const [v, t] of Object.entries(PIEZA)) m.push({ topic: "ns=1;s=Trazabilidad.UltimaPieza." + v, datatype: t });
for (const [v, t] of Object.entries(COLADA)) m.push({ topic: "ns=1;s=Trazabilidad.UltimaColada." + v, datatype: t });
m.push({ topic: "ns=1;s=Mantenimiento.Averia", datatype: "Int32" });
node.status({ text: m.length + " variables" });
return [m];

// ENTRADA: un mensaje por variable (msg.topic = NodeId, msg.payload = valor)
// SALIDA:  msg.payload = todas las variables recibidas, agrupadas por activo

if (!String(msg.topic).startsWith("ns=")) {
    return null;          // avisos del propio cliente (p. ej. subscriptionId): no son datos
}
let valor = msg.payload;
// algunas versiones envían el valor dentro de { value: ... }
while (valor !== null && typeof valor === "object" && "value" in valor) {
    valor = valor.value;
}
if (typeof valor === "number") {
    valor = Math.round(valor * 1000) / 1000;      // 3 decimales
}

// "ns=1;s=IF-01.TemperaturaMetal"  →  ["IF-01", "TemperaturaMetal"]
const partes = String(msg.topic).split("s=").pop().split(".");
const variable = partes.pop();

const central = flow.get("planta") || {};
let sitio = central;
for (const p of partes) {                         // crea IF-01, COL-01, KPIs...
    sitio[p] = sitio[p] || {};
    sitio = sitio[p];
}
sitio[variable] = valor;
central.timestamp = new Date().toISOString();
flow.set("planta", central);

msg.payload = central;
return msg;

// ENTRADA: la planta agrupada (un mensaje por cada variable que cambia)
// SALIDA:  la pieza, una sola vez, cuando QC-01 inspecciona una nueva y ya han llegado todos sus campos

const p = (msg.payload.Trazabilidad || {}).UltimaPieza;
if (!p || !p.Id) return null;
// los campos de una pieza llegan como varios cambios OPC UA seguidos: esperamos a que esté completa
if (p.Id === context.get("ultima")) return null;
const campos = ["Lote", "TemperaturaColada", "HumedadArena", "Inoculada", "TiempoEnfriamiento",
                "TemperaturaDesmoldeo", "Desviacion", "Resultado", "Defecto"];
if (campos.some(c => p[c] === undefined)) return null;
clearTimeout(context.get("t"));
context.set("t", setTimeout(() => {               // 300 ms: que lleguen todos los campos de la misma pieza
    const actual = flow.get("planta").Trazabilidad.UltimaPieza;
    if (actual.Id === context.get("ultima")) return;
    context.set("ultima", actual.Id);
    node.send({ payload: Object.assign({}, actual), contexto: flow.get("planta") });
}, 300));
return null;

// ENTRADA: la pieza inspeccionada (msg.payload) y la planta (msg.contexto)
// SALIDA:  msg.payload = una fila plana para el conjunto "fundicion"

const p = msg.payload;
msg.payload = {
    pieza:          p.Id,
    molde:          p.Molde,
    lote:           p.Lote,
    // condiciones que se conocen AL COLAR (47 min antes de la inspección)
    t_colada:       p.TemperaturaColada,
    humedad:        p.HumedadArena,
    inoculada:      p.Inoculada ? 1 : 0,
    // lo que se sabe después
    t_enfriamiento: p.TiempoEnfriamiento,
    t_desmoldeo:    p.TemperaturaDesmoldeo,
    desviacion:     p.Desviacion,
    // la etiqueta: lo que dijo el escáner
    rechazo:        p.Resultado === "RECHAZO" ? 1 : 0,
    defecto:        p.Defecto,
    // la avería activa EN EL MOMENTO DE LA INSPECCIÓN (no cuando se coló la pieza)
    averia:         (msg.contexto.Mantenimiento || {}).Averia ?? 0
};
node.status({ fill: msg.payload.rechazo ? "red" : "green", shape: "dot", text: `${p.Id} · ${p.Resultado}` });
return msg;

// ENTRADA: "empezar" o "parar" (botones)
// SALIDA:  escrituras OPC UA: velocidad ×20 y la avería de cada tramo
// Cada tramo dura 3 min reales = 1 h de planta. 7 tramos ≈ 21 min ≈ 430 piezas.

const TRAMOS = [0, 5, 0, 6, 0, 7, 0];     // 5 humedad de arena · 6 inoculación · 7 termopar de IF-01
const MINUTOS = 3;
const escribir = (id, tipo, valor) => ({ topic: "ns=1;s=" + id, datatype: tipo, payload: valor });
const fin = [escribir("Mantenimiento.Averia", "Int32", 0), escribir("Simulacion.Velocidad", "Double", 1)];

clearInterval(context.get("reloj"));
if (msg.payload !== "empezar") {
    node.status({ fill: "grey", shape: "dot", text: "campaña parada" });
    return [fin];
}
let paso = 0;
const tramo = () => {
    if (paso >= TRAMOS.length) {
        clearInterval(context.get("reloj"));
        node.status({ fill: "grey", shape: "dot", text: "campaña terminada" });
        node.send([fin]);
        return;
    }
    node.status({ fill: TRAMOS[paso] ? "orange" : "green", shape: "dot",
                  text: `tramo ${paso + 1}/${TRAMOS.length} · avería ${TRAMOS[paso]}` });
    const ordenes = [escribir("Mantenimiento.Averia", "Int32", TRAMOS[paso])];
    if (paso === 0) ordenes.push(escribir("Simulacion.Velocidad", "Double", 20));
    node.send([ordenes]);
    paso++;
};
tramo();
context.set("reloj", setInterval(tramo, MINUTOS * 60 * 1000));
return null;
